  "summary": "The customer called to report unstable internet dropping every ten minutes and to pay their outstanding balance. The agent processed the payment and raised a network ticket to fix the exchange issue. The network problem is pending resolution.",
  "reasons": [
    {
      "evidence": [
        {
          "turn_id": 2,
          "quote": "My internet has been dropping every ten minutes for the last three days."
        }
      ],
      "label": "network",
      "confidence": 1.0,
      "rationale": "The customer explicitly complains about internet connection drops and instability."
    },
    {
      "evidence": [
        {
          "turn_id": 9,
          "quote": "I also need to pay my outstanding balance so it doesn't get cut off."
        }
      ],
      "label": "billing",
      "confidence": 1.0,
      "rationale": "The customer mentions needing to pay an outstanding balance to avoid service disconnection."
    }
  ],
  "resolution": {
    "evidence": [
      {
        "turn_id": 12,
        "quote": "I am going to raise a network ticket to have the exchange port reset and monitored."
      }
    ],
    "status": "partial",
    "confidence": 1.0,
    "rationale": "The billing issue was resolved via payment, but the main network issue is only addressed by raising a ticket for future fix, meaning it is not fully resolved during the call."
  },
  "churn": {
    "evidence": [
      {
        "turn_id": 7,
        "quote": "I just want this fixed now."
      }
    ],
    "risk_score": 0.2,
    "flag": false,
    "rationale": "The customer is angry and wants the issue fixed immediately, but does not threaten to cancel, switch providers, or port out."
  }
}
